using System;using System.IO;using System.Linq;using System.Reflection;using System.Text;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioWireDepthValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static int checks;static StringBuilder report=new StringBuilder();
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);checks++;}
 static void Set(object o,string n,object v)=>o.GetType().GetField(n,F).SetValue(o,v);
 static Color32[] Render(StudioModelEditor ed,SceneView view,RenderTexture rt,Mesh cover,Material solid,bool blocked,bool ownSurface=false,float coverDistance=1.5f){var old=RenderTexture.active;RenderTexture.active=rt;GL.PushMatrix();try{GL.Clear(true,true,Color.white);GL.LoadProjectionMatrix(view.camera.projectionMatrix);GL.modelview=view.camera.worldToCameraMatrix;if(ownSurface){solid.SetPass(0);Graphics.DrawMeshNow(ed.Document.nodes[0].mesh,ed.Transforms[0].localToWorldMatrix);}if(blocked){solid.SetPass(0);Graphics.DrawMeshNow(cover,Matrix4x4.TRS(view.camera.transform.position+view.camera.transform.forward*coverDistance,view.camera.transform.rotation,Vector3.one*100));}typeof(StudioModelEditor).GetMethod("DrawVisibleObjectWireframes",F).Invoke(ed,new object[]{view.camera});var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);try{t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();return t.GetPixels32();}finally{Object.DestroyImmediate(t);}}finally{GL.PopMatrix();RenderTexture.active=old;}}
 static int Ink(Color32[] p)=>p.Count(c=>c.r<180&&c.g<180&&c.b<180);
 static void Save(Color32[] pixels,string name){var image=new Texture2D(256,256,TextureFormat.RGBA32,false);image.SetPixels32(pixels);image.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../wire-depth-"+name+".png")),image.EncodeToPNG());Object.DestroyImmediate(image);}
 public static void Run(){int exit=0;try{Validate();AuthoredFaces();report.AppendLine("PASS "+checks+" wire depth render assertions");}catch(Exception e){exit=1;report.AppendLine(e.ToString());}File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../wire-depth-result.txt")),report.ToString());EditorApplication.Exit(exit);}
 static void AuthoredFaces(){
 var view=ScriptableObject.CreateInstance<SceneView>();var rt=new RenderTexture(256,256,24);rt.Create();view.camera.targetTexture=rt;view.camera.fieldOfView=60;view.camera.nearClipPlane=.03f;view.camera.farClipPlane=100;view.camera.orthographicSize=1.5f;view.camera.transform.position=new Vector3(0,0,-3);view.camera.transform.rotation=Quaternion.identity;var cover=StudioModelDocument.BuildPrimitive(PrimitiveType.Quad);var solid=new Material(Shader.Find("Hidden/StudioValidationSolid"));
 try{foreach(bool concave in new[]{false,true}){
 var vertices=concave?new[]{new Vector3(-.8f,-.8f,0),new Vector3(.8f,-.8f,.1f),new Vector3(.8f,-.1f,.2f),new Vector3(-.1f,-.1f,.2f),new Vector3(-.1f,.8f,0),new Vector3(-.8f,.8f,0)}:new[]{new Vector3(-.8f,-.8f,0),new Vector3(.8f,-.8f,.1f),new Vector3(.8f,.8f,.2f),new Vector3(-.8f,.8f,0)};
 var indices=concave?new[]{0,1,2,0,2,3,0,3,5,3,4,5}:new[]{0,1,2,0,2,3};var mesh=new Mesh();mesh.vertices=vertices;mesh.triangles=indices;var doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(new StudioModelDocument.Node{mesh=mesh,cutPolygons=new[]{0,vertices.Length}.Concat(Enumerable.Range(0,vertices.Length)).ToArray(),cutTriangles=indices});
 using(var ed=new StudioModelEditor(()=>{})){ed.Load(doc);ed.SelectionWireframeLines(0);var cache=(System.Collections.IDictionary)typeof(StudioModelEditor).GetField("selectionWireframes",F).GetValue(ed);var wire=cache[doc.nodes[0]];var wi=(int[])wire.GetType().GetField("indices",F).GetValue(wire);var adj=(int[])wire.GetType().GetField("adjacent",F).GetValue(wire);Check(wi.Length==vertices.Length*2,"Render diagonals became editable wire edges");for(int e=0;e<wi.Length/2;e++){int a=wi[e*2],b=wi[e*2+1],c=adj[e*2]-1;Check(c>=0&&Enumerable.Range(0,indices.Length/3).Any(t=>new[]{indices[t*3],indices[t*3+1],indices[t*3+2]}.OrderBy(v=>v).SequenceEqual(new[]{a,b,c}.OrderBy(v=>v))),"Wire depth adjacency is not an actual authored render triangle");}
 foreach(bool ortho in new[]{false,true}){view.camera.orthographic=ortho;Set(ed,"displayXray",false);var visible=Render(ed,view,rt,cover,solid,false,true);Check(Ink(visible)>150,"Authored polygon surface lost boundary wires");var hidden=Render(ed,view,rt,cover,solid,true);Check(Ink(hidden)==0,"Authored polygon wires leak through foreground cover");Set(ed,"displayXray",true);Check(Ink(Render(ed,view,rt,cover,solid,true))>150,"Authored polygon X-ray lost wires");}
 }Object.DestroyImmediate(mesh);Object.DestroyImmediate(doc);
 }}finally{view.camera.targetTexture=null;Object.DestroyImmediate(solid);Object.DestroyImmediate(cover);Object.DestroyImmediate(view);Object.DestroyImmediate(rt);}
 }
 static void Validate(){var shader=Shader.Find("Hidden/MashBox/ModelerWireBatch");Check(shader&&shader.isSupported&&!ShaderUtil.ShaderHasError(shader),"Wire shader compile/support");StudioSettings.Current.hideObjectWireframe=false;var view=ScriptableObject.CreateInstance<SceneView>();var rt=new RenderTexture(256,256,24);rt.Create();view.camera.targetTexture=rt;view.camera.nearClipPlane=.03f;view.camera.farClipPlane=100;view.camera.fieldOfView=60;view.camera.orthographicSize=1.5f;var cover=StudioModelDocument.BuildPrimitive(PrimitiveType.Quad);var solid=new Material(Shader.Find("Hidden/StudioValidationSolid"));int leaking=0;bool saved=false;
 try{foreach(bool ortho in new[]{false,true})foreach(float thin in new[]{.001f,.003f,.01f,.03f}){
 var mesh=new Mesh();mesh.vertices=new[]{new Vector3(-.8f,0,0),new Vector3(.8f,0,0),new Vector3(0,thin,2)};mesh.triangles=new[]{0,1,2};var doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(new StudioModelDocument.Node{name="Unselected hidden triangle",mesh=mesh,cutPolygons=new[]{0,3,0,1,2},cutTriangles=mesh.triangles});
 using(var ed=new StudioModelEditor(()=>{})){ed.Load(doc);view.camera.orthographic=ortho;
 int uploads=-1;for(int jitter=0;jitter<5;jitter++){view.camera.transform.position=new Vector3(jitter*.0007f,jitter*.0003f,-3);view.camera.transform.rotation=Quaternion.Euler(jitter*.01f,jitter*.01f,0);Set(ed,"displayXray",false);var hidden=Render(ed,view,rt,cover,solid,true);int ink=Ink(hidden);report.AppendLine("ortho="+ortho+" thin="+thin+" jitter="+jitter+" hidden_pixels="+ink);if(ink>0){leaking+=ink;if(!saved){Save(hidden,"hidden");saved=true;}}var repeated=Render(ed,view,rt,cover,solid,true);Check(hidden.SequenceEqual(repeated),"Stationary hidden result changed");Set(ed,"displayXray",true);var xray=Render(ed,view,rt,cover,solid,true);Check(Ink(xray)>100,"X-ray no longer reveals hidden edges");Set(ed,"displayXray",false);var visible=Render(ed,view,rt,cover,solid,false);Check(Ink(visible)>100,"Unselected visible wire vanished");var own=Render(ed,view,rt,cover,solid,false,true);Check(Ink(own)>100,"Own surface hides wire");var close=Render(ed,view,rt,cover,solid,true,false,2.999f);Check(Ink(close)==0,"Small depth separation leaks through cover");if(uploads<0)uploads=ed.WireBatchUploads;Check(uploads==ed.WireBatchUploads,"Camera redraw reuploaded geometry");if(!saved){Save(hidden,"hidden-after");Save(visible,"visible-after");saved=true;}}
 }Object.DestroyImmediate(mesh);Object.DestroyImmediate(doc);}
 Check(leaking==0,"Unselected hidden edges leak through distant face: "+leaking+" pixels");
 }finally{view.camera.targetTexture=null;Object.DestroyImmediate(solid);Object.DestroyImmediate(cover);Object.DestroyImmediate(view);Object.DestroyImmediate(rt);}}
}
